commit 58395e9edfaa79e8e5870b88665897936a3b0799
Author: Agent Team <agent@ccat.dev>
Date:   Mon Jun 15 16:51:29 2026 +0800

    fix: 被举报评论已删除时管理员无法处理举报

    两个根因：(1) ddl-auto: update 导致 Flyway VARCHAR 被 Hibernate 6 漂移为 ENUM，
    JPA save() 全量 UPDATE 时产生 Data truncated；(2) 前端 handleResolveReport
    未处理目标内容已被作者删除的场景，举报卡在 PENDING。
    修复：关闭 ddl-auto，增加 V2 Flyway migration 显式声明 ENUM；handleReport
    支持 adminComment；前端检查评论状态，已删则跳过删除直接归档 RESOLVED。

diff --git a/frontend/src/api/report.ts b/frontend/src/api/report.ts
index c0fb04e..2006a2b 100644
--- a/frontend/src/api/report.ts
+++ b/frontend/src/api/report.ts
@@ -39,6 +39,10 @@ export async function adminGetReports(): Promise<Report[]> {
  * Handle a report status
  * PUT /api/admin/reports/{id}
  */
-export async function adminHandleReport(id: number, status: 'RESOLVED' | 'DISMISSED'): Promise<void> {
-  await client.put(`/admin/reports/${id}`, { status });
+export async function adminHandleReport(
+  id: number,
+  status: 'RESOLVED' | 'DISMISSED',
+  adminComment?: string
+): Promise<void> {
+  await client.put(`/admin/reports/${id}`, { status, ...(adminComment ? { adminComment } : {}) });
 }
diff --git a/frontend/src/pages/admin/ContentModeration.tsx b/frontend/src/pages/admin/ContentModeration.tsx
index 6b0d19f..3fb8ceb 100644
--- a/frontend/src/pages/admin/ContentModeration.tsx
+++ b/frontend/src/pages/admin/ContentModeration.tsx
@@ -93,8 +93,8 @@ export default function ContentModeration() {

   // 处理举报
   const handleReportMutation = useMutation({
-    mutationFn: ({ id, status }: { id: number; status: 'RESOLVED' | 'DISMISSED' }) =>
-      adminHandleReport(id, status),
+    mutationFn: ({ id, status, adminComment }: { id: number; status: 'RESOLVED' | 'DISMISSED'; adminComment?: string }) =>
+      adminHandleReport(id, status, adminComment),
     onSuccess: () => {
       queryClient.invalidateQueries({ queryKey: ['admin', 'reports'] });
       setSuccess('举报处理成功');
@@ -105,6 +105,30 @@ export default function ContentModeration() {
   });

   const handleResolveReport = async (report: any) => {
+    // 检查目标内容是否已被作者删除
+    let targetAlreadyDeleted = false;
+    if (report.targetType === 'COMMENT') {
+      const targetComment = reportComments.find((c: any) => c.id === report.targetId);
+      if (!targetComment || targetComment.status === 'DELETED') {
+        targetAlreadyDeleted = true;
+      }
+    }
+
+    if (targetAlreadyDeleted) {
+      if (!confirm(`该评论已被作者自行删除，是否直接标记举报为已处理？`)) return;
+      try {
+        await handleReportMutation.mutateAsync({
+          id: report.id,
+          status: 'RESOLVED',
+          adminComment: '评论已被作者自行删除，举报直接归档'
+        });
+        setSuccess('举报已归档（内容已被作者删除）');
+      } catch (err: any) {
+        setError(err.response?.data?.message || '处理失败');
+      }
+      return;
+    }
+
     if (!confirm(`确定要处理此举报并删除该内容吗？此操作不可恢复。`)) return;

     try {
diff --git a/microservices/content-service/src/main/java/com/cc91/contentservice/controller/ReportController.java b/microservices/content-service/src/main/java/com/cc91/contentservice/controller/ReportController.java
index 72b6733..d8b8bb2 100644
--- a/microservices/content-service/src/main/java/com/cc91/contentservice/controller/ReportController.java
+++ b/microservices/content-service/src/main/java/com/cc91/contentservice/controller/ReportController.java
@@ -73,14 +73,17 @@ public class ReportController {
         if (status == null || status.trim().isEmpty()) {
             throw new BadRequestException("处理状态不能为空");
         }
-        Report report = reportService.handleReport(id, status);
+        Report report = reportService.handleReport(id, status, request.getAdminComment());
         return ResponseEntity.ok(ApiResponse.success("举报已处理", report));
     }

     public static class HandleReportRequest {
         private String status;
+        private String adminComment;
         public String getStatus() { return status; }
         public void setStatus(String status) { this.status = status; }
+        public String getAdminComment() { return adminComment; }
+        public void setAdminComment(String adminComment) { this.adminComment = adminComment; }
     }

     private String getCurrentUsername() {
diff --git a/microservices/content-service/src/main/java/com/cc91/contentservice/service/ReportService.java b/microservices/content-service/src/main/java/com/cc91/contentservice/service/ReportService.java
index 228f697..7652b39 100644
--- a/microservices/content-service/src/main/java/com/cc91/contentservice/service/ReportService.java
+++ b/microservices/content-service/src/main/java/com/cc91/contentservice/service/ReportService.java
@@ -3,6 +3,7 @@ package com.cc91.contentservice.service;
 import com.cc91.contentservice.client.UserInfoDTO;
 import com.cc91.contentservice.client.UserServiceClient;
 import com.cc91.contentservice.entity.Report;
+import com.cc91.contentservice.exception.BadRequestException;
 import com.cc91.contentservice.exception.ResourceNotFoundException;
 import com.cc91.contentservice.repository.ReportRepository;
 import org.slf4j.Logger;
@@ -95,12 +96,22 @@ public class ReportService {
      * @return 更新后的 Report 实体
      */
     @Transactional
-    public Report handleReport(Long id, String status) {
+    public Report handleReport(Long id, String status, String adminComment) {
         Report report = reportRepository.findById(id)
                 .orElseThrow(() -> new ResourceNotFoundException("举报不存在"));

-        report.setStatus(Report.ReportStatus.valueOf(status.toUpperCase()));
+        Report.ReportStatus targetStatus;
+        try {
+            targetStatus = Report.ReportStatus.valueOf(status.toUpperCase());
+        } catch (IllegalArgumentException e) {
+            throw new BadRequestException("无效的处理状态: " + status);
+        }
+
+        report.setStatus(targetStatus);
         report.setReviewedAt(LocalDateTime.now());
+        if (adminComment != null) {
+            report.setAdminComment(adminComment);
+        }
         report = reportRepository.save(report);

         logger.info("举报处理完成: id={}, status={}", id, status);
diff --git a/microservices/content-service/src/main/resources/application.yml b/microservices/content-service/src/main/resources/application.yml
index 700e917..ba4ed63 100644
--- a/microservices/content-service/src/main/resources/application.yml
+++ b/microservices/content-service/src/main/resources/application.yml
@@ -9,7 +9,7 @@ spring:
     password: ${DB_PASSWORD}
   jpa:
     hibernate:
-      ddl-auto: update
+      ddl-auto: none
   flyway:
     enabled: true
     locations: classpath:db/migration
diff --git a/microservices/content-service/src/main/resources/db/migration/V2__Ensure_Report_Enum.sql b/microservices/content-service/src/main/resources/db/migration/V2__Ensure_Report_Enum.sql
new file mode 100644
index 0000000..bc9a4c7
--- /dev/null
+++ b/microservices/content-service/src/main/resources/db/migration/V2__Ensure_Report_Enum.sql
@@ -0,0 +1,4 @@
+-- Ensure reports columns use ENUM matching @Enumerated(EnumType.STRING) entities.
+-- Hibernate 6 MySQL dialect prefers ENUM; this formalises the prior ddl-auto drift.
+ALTER TABLE reports MODIFY COLUMN target_type ENUM('POST','COMMENT') NOT NULL;
+ALTER TABLE reports MODIFY COLUMN status ENUM('PENDING','REVIEWED','RESOLVED','DISMISSED') NOT NULL DEFAULT 'PENDING';

