1	import { useState, useMemo } from 'react';
2	import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
3	import {
4	  adminGetPosts, adminUpdatePostStatus, adminDeletePost,
5	  adminGetComments, adminDeleteComment
6	} from '../../api/admin';
7	import { adminGetReports, adminHandleReport } from '../../api/report';
8	import ErrorMessage from '../../components/ErrorMessage';
9	import { queryKeys } from '../../lib/queryKeys';
10	
11	type TabType = 'posts' | 'comments' | 'reports';
12	
13	/**
14	 * 内容审核页面 - 帖子与评论审核
15	 */
16	export default function ContentModeration() {
17	  const queryClient = useQueryClient();
18	  const [activeTab, setActiveTab] = useState<TabType>('posts');
