import { useState, type FormEvent } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import ErrorMessage from '../components/ErrorMessage';
import client from '../api/client';

/**
 * CC98 风格用户登录页面
 */
export default function LoginPage() {
  const navigate = useNavigate();
  const { login } = useAuth();
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    setError('');
    setIsLoading(true);

    try {
      const response = await client.post('/auth/login', {
        username,
        password,
      });

      const { accessToken, refreshToken } = response.data;

      // Store tokens FIRST so the axios interceptor can use them
      sessionStorage.setItem('access_token', accessToken);
      if (refreshToken) {
        sessionStorage.setItem('refresh_token', refreshToken);
      }

      // Now fetch user role and avatar
      let userRole = 'USER';
      let avatarUrl: string | null = null;
      try {
        const userResponse = await client.get(`/users/${username}`);
        userRole = userResponse.data.role || 'USER';
        avatarUrl = userResponse.data.avatarUrl || null;
      } catch (err) {
        // If user info fetch fails, default to regular user
        console.error('Failed to fetch user role', err);
      }

      login(username, accessToken, userRole, avatarUrl);
      navigate(`/profile/${username}`);
    } catch (err: any) {
      const status = err.response?.status;
      const message = err.response?.data?.message;
      if (status === 403) {
        setError(message || '该账号已被封禁，如有疑问请联系管理员。');
      } else if (status === 423) {
        setError(message || '账号已被临时锁定，请稍后再试。');
      } else {
        setError(message || '登录失败，请检查用户名或密码。');
      }
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="cc98-auth-page container">
      <div className="cc98-auth-card">
        <div className="cc98-auth-header">
          <i className="fa fa-sign-in"></i> User Login
        </div>

        <form onSubmit={handleSubmit} className="cc98-auth-form">
          {/* Username */}
          <div className="cc98-form-group">
            <label htmlFor="username">Username</label>
            <input
              id="username"
              type="text"
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              disabled={isLoading}
              placeholder="请输入您的账号用户名"
              className="cc98-form-control"
              required
              autoFocus
            />
          </div>

          {/* Password */}
          <div className="cc98-form-group">
            <label htmlFor="password">Password</label>
            <input
              id="password"
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              disabled={isLoading}
              placeholder="请输入登录密码"
              className="cc98-form-control"
              required
            />
          </div>

          {error && <ErrorMessage message={error} onDismiss={() => setError('')} />}

          {/* Login Button */}
          <button
            type="submit"
            className="cc98-btn btn-publish btn-block"
            disabled={isLoading}
            style={{ width: '100%', marginTop: '1.5rem' }}
          >
            {isLoading ? <i className="fa fa-spinner fa-spin"></i> : 'Login'}
          </button>
        </form>

        <div className="cc98-auth-footer">
          <p>
            还没有账号？ <Link to="/register" className="auth-link">立即注册</Link>
          </p>
          <p style={{ marginTop: '0.4rem' }}>
            <Link to="/forgot-password" className="auth-link text-muted">忘记密码？</Link>
